          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 500 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 5000, costCents: 1200 },
    ];

    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weightGrams set)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine("a", undefined, 3)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(0);
    });

    it("selects first bracket when weight is within it", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 200g * 2 = 400g ≤ 500g → 300
      const lines = [makeLine("a", 200, 2)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 500g exactly → first bracket (≤ 500) → 300
      const lines = [makeLine("a", 500, 1)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(300);
    });

    it("selects next bracket when weight is 1g over boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 501g → second bracket (≤ 1000) → 600
      const lines = [makeLine("a", 501, 1)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(600);
    });

    it("selects highest bracket at its boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 5000g → third bracket → 1200
      const lines = [makeLine("a", 5000, 1)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 2000);
      // 5001g → overflow → 2000
      const lines = [makeLine("a", 5001, 1)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(2000);
    });

    it("falls back to heaviest bracket cost when no overflow specified", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 10000g → no overflow → last bracket costCents = 1200
      const lines = [makeLine("a", 10000, 1)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(1200);
    });

    it("sorts brackets regardless of input order", () => {
      const unsorted = [
        { upToGrams: 1000, costCents: 600 },
        { upToGrams: 500, costCents: 300 },
      ];
      const calc = new WeightBasedShippingCalculator(unsorted);
      // 400g → first sorted bracket (500g) → 300
      const lines = [makeLine("a", 400, 1)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(300);
    });

    it("sums weight across multiple lines", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 200*2 + 300*1 = 700g → second bracket (≤ 1000) → 600
      const lines = [makeLine("a", 200, 2), makeLine("b", 300, 1)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(600);
    });
  });
});

